// ─── File: AtomicDedupDemo.java ───
// Runnable demo: naive check-then-act double-processes; atomic+single-tx does not.
package com.bank.atomicdedup;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class AtomicDedupDemo {

    private static final Logger log = Logger.getLogger("AtomicDedup");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // ---- NAIVE under concurrency: expect double credit ----
        InboxStore naiveInbox = new InboxStore();
        BalanceStore naiveBal = new BalanceStore();
        naiveBal.set("CUR3001", new BigDecimal("250000"));
        NaiveConsumer naive = new NaiveConsumer(naiveInbox, naiveBal);
        concurrentDeliver("EVT-1", () -> naive.onEvent("EVT-1", "CUR3001",
                new BigDecimal("50000")));
        log.warning(() -> "NAIVE CUR3001 = Rs." + naiveBal.get("CUR3001")
                + " (should be 300000; double-processed if 350000)");

        // ---- SAFE under concurrency: expect single credit ----
        InboxStore safeInbox = new InboxStore();
        BalanceStore safeBal = new BalanceStore();
        safeBal.set("CUR3001", new BigDecimal("250000"));
        SafeConsumer safe = new SafeConsumer(safeInbox, safeBal);
        concurrentDeliver("EVT-2", () -> safe.onEvent("EVT-2", "CUR3001",
                new BigDecimal("50000")));
        log.info(() -> "SAFE CUR3001 = Rs." + safeBal.get("CUR3001")
                + " (correctly 300000)");

        // ---- SAFE under crash: process+mark in one tx → redelivery safe ----
        safe.onEventWithCrashBeforeAck("EVT-3", "CUR3001", new BigDecimal("10000"));
        safe.onEvent("EVT-3", "CUR3001", new BigDecimal("10000")); // redelivery
        log.info(() -> "SAFE after crash+redelivery CUR3001 = Rs."
                + safeBal.get("CUR3001") + " (credited once)");
    }

    static void concurrentDeliver(String id, Runnable handler) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch gate = new CountDownLatch(1);
        for (int i = 0; i < 2; i++) {
            pool.submit(() -> { try { gate.await(); } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); } handler.run(); });
        }
        gate.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }
}

// ─── store/InboxStore.java ───
class InboxStore {
    private final java.util.Set<String> processed =
            java.util.concurrent.ConcurrentHashMap.newKeySet();
    // Naive read.
    boolean alreadyProcessed(String id) { return processed.contains(id); }
    // Naive mark (separate step).
    void markProcessed(String id) { processed.add(id); }
    // Atomic claim: INSERT ... UNIQUE(event_id) — true only for the winner.
    boolean claimAtomically(String id) { return processed.add(id); }
}

// ─── store/BalanceStore.java ───
class BalanceStore {
    private final java.util.concurrent.ConcurrentHashMap<String, BigDecimal> db =
            new java.util.concurrent.ConcurrentHashMap<>();
    void set(String id, BigDecimal b) { db.put(id, b); }
    void credit(String id, BigDecimal amt) { db.merge(id, amt, BigDecimal::add); }
    BigDecimal get(String id) { return db.get(id); }
}

// ─── naive/NaiveConsumer.java (BUGGY check-then-act) ───
class NaiveConsumer {
    private final InboxStore inbox;
    private final BalanceStore balances;
    NaiveConsumer(InboxStore inbox, BalanceStore balances) {
        this.inbox = inbox; this.balances = balances;
    }
    void onEvent(String id, String account, BigDecimal amount) {
        if (!inbox.alreadyProcessed(id)) {   // RACE WINDOW starts here
            balances.credit(account, amount); // both consumers reach here
            inbox.markProcessed(id);          // marked too late
        }
    }
}

// ─── safe/SafeConsumer.java (atomic claim + single transaction) ───
class SafeConsumer {
    private static final Logger log = Logger.getLogger("AtomicDedup");
    private final InboxStore inbox;
    private final BalanceStore balances;
    SafeConsumer(InboxStore inbox, BalanceStore balances) {
        this.inbox = inbox; this.balances = balances;
    }
    // Fix 1: atomic unique claim decides the single winner.
    // Fix 2: claim + credit are one transaction (simulated by ordering the
    //         durable claim BEFORE the effect and committing together).
    synchronized void onEvent(String id, String account, BigDecimal amount) {
        if (!inbox.claimAtomically(id)) {     // only ONE consumer wins the INSERT
            log.info(() -> "DUPLICATE " + id + " lost the claim → skip");
            return;
        }
        balances.credit(account, amount);     // committed in the SAME tx as claim
        log.info(() -> "SAFE credited " + account + " Rs." + amount + " for " + id);
    }
    // Models a crash: because claim+credit commit together, if we crash before
    // ack the WHOLE transaction either committed (then redelivery is skipped)
    // or not (then redelivery safely redoes it). Here it committed.
    void onEventWithCrashBeforeAck(String id, String account, BigDecimal amount) {
        onEvent(id, account, amount);         // transaction committed
        log.warning(() -> "CRASH before ack for " + id + " (tx already committed)");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
